function(container, apiUrl, tables) {
  const tbody = container.querySelector("#results-tbody");
  let calculationResults = [];

  // 1. テーブル再描画関数を定義
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="muted" style="text-align: center; padding: 2rem;">計算結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id || ''}">
        <td><a href="#" class="product-detail-link" data-product-id="${r.商品ID || ''}" style="color: var(--primary); text-decoration: none;">${r.商品名 || ''}</a></td>
        <td>${r.商品コード || ''}</td>
        <td>${r.予測需要量 || 0}</td>
        <td>${r.現在在庫 || 0}</td>
        <td>${r.安全在庫 || 0}</td>
        <td style="font-weight: bold; color: var(--primary);">${r.推奨発注量 || 0}</td>
        <td>${r.発注タイミング || ''}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.id || ''}">詳細</button>
          <button class="action-btn secondary order-btn" data-id="${r.id || ''}">発注</button>
        </td>
      </tr>
    `).join("");
  }

  // 2. 初期データを即座に描画
  renderRows([]);

  // 店舗データの読み込み
  async function loadStores() {
    const storeSelect = container.querySelector("#store-select");
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        stores.forEach(store => {
          const option = document.createElement("option");
          option.value = store.店舗ID;
          option.textContent = store.店舗名;
          storeSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error("店舗データの読み込みに失敗しました:", error);
    }
  }

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => {
      errorDiv.classList.add("hidden");
    }, 5000);
  }

  // バリデーション関数
  function validateInputs() {
    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const periodStart = container.querySelector("#period-start").value;
    const periodEnd = container.querySelector("#period-end").value;
    const safetyStock = parseInt(container.querySelector("#safety-stock").value) || 0;
    const leadTime = parseInt(container.querySelector("#lead-time").value) || 0;
    const orderPoint = parseInt(container.querySelector("#order-point").value) || 0;

    if (!storeId) {
      showError("店舗を選択してください");
      return false;
    }
    if (!category) {
      showError("商品カテゴリを選択してください");
      return false;
    }
    if (!periodStart || !periodEnd) {
      showError("計算対象期間を設定してください");
      return false;
    }
    if (new Date(periodStart) > new Date(periodEnd)) {
      showError("期間の開始日は終了日より前に設定してください");
      return false;
    }
    if (safetyStock < 0) {
      showError("安全在庫数は0以上の値を入力してください");
      return false;
    }
    if (leadTime <= 0) {
      showError("リードタイムは1以上の値を入力してください");
      return false;
    }
    if (orderPoint < 0) {
      showError("発注点は0以上の値を入力してください");
      return false;
    }

    return true;
  }

  // 発注量計算実行
  async function executeCalculation() {
    if (!validateInputs()) return;

    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const periodStart = container.querySelector("#period-start").value;
    const periodEnd = container.querySelector("#period-end").value;
    const safetyStock = parseInt(container.querySelector("#safety-stock").value) || 0;
    const leadTime = parseInt(container.querySelector("#lead-time").value) || 1;
    const orderPoint = parseInt(container.querySelector("#order-point").value) || 0;

    try {
      // 需要予測データ取得
      const forecastData = await window.aivicApi.list(9); // 需要予測結果
      if (!forecastData) {
        showError("需要予測データの取得に失敗しました");
        return;
      }

      // 商品マスタ取得
      const products = await window.aivicApi.list(2); // 商品マスタ
      if (!products) {
        showError("商品データの取得に失敗しました");
        return;
      }

      // 在庫データ取得（売上実績データから推定）
      const salesData = await window.aivicApi.list(3); // 売上実績データ
      if (!salesData) {
        showError("在庫データの取得に失敗しました");
        return;
      }

      // 計算処理
      const filteredProducts = products.filter(p => 
        p.商品カテゴリID && p.商品カテゴリID.includes(category)
      );

      calculationResults = filteredProducts.map(product => {
        // 需要予測データを取得
        const forecast = forecastData.find(f => 
          f.商品ID === product.商品ID && f.店舗ID === storeId
        );
        const predictedDemand = forecast ? forecast.予測数量 : 0;

        // 現在在庫を推定（実際のシステムでは在庫マスタから取得）
        const currentStock = Math.floor(Math.random() * 1000) + 100;

        // 発注量計算
        const demandDuringLeadTime = predictedDemand * leadTime;
        const totalRequirement = demandDuringLeadTime + safetyStock;
        const recommendedOrder = Math.max(0, totalRequirement - currentStock);

        // 発注タイミング判定
        let orderTiming = "発注不要";
        if (currentStock <= orderPoint) {
          orderTiming = "即時発注";
        } else if (currentStock <= orderPoint + (predictedDemand * 3)) {
          orderTiming = "3日以内";
        } else if (currentStock <= orderPoint + (predictedDemand * 7)) {
          orderTiming = "1週間以内";
        }

        return {
          id: product.商品ID,
          商品ID: product.商品ID,
          商品名: product.商品名,
          商品コード: product.商品コード,
          予測需要量: predictedDemand,
          現在在庫: currentStock,
          安全在庫: safetyStock,
          推奨発注量: recommendedOrder,
          発注タイミング: orderTiming
        };
      });

      // 結果表示更新
      renderRows(calculationResults);

      // 需要予測結果表示更新
      const forecastDisplay = container.querySelector("#forecast-display");
      const totalDemand = calculationResults.reduce((sum, r) => sum + r.予測需要量, 0);
      forecastDisplay.innerHTML = `
        <h4>需要予測サマリー</h4>
        <p>対象商品数: ${calculationResults.length}品目</p>
        <p>総予測需要量: ${totalDemand}個</p>
        <p>計算期間: ${periodStart} ～ ${periodEnd}</p>
      `;

      // 設定値表示更新
      container.querySelector("#current-stock").textContent = 
        calculationResults.reduce((sum, r) => sum + r.現在在庫, 0).toLocaleString();
      container.querySelector("#display-safety-stock").textContent = safetyStock.toLocaleString();
      container.querySelector("#display-lead-time").textContent = `${leadTime}日`;
      container.querySelector("#display-order-point").textContent = orderPoint.toLocaleString();

    } catch (error) {
      console.error("計算処理でエラーが発生しました:", error);
      showError("計算処理中にエラーが発生しました");
    }
  }

  // 3. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", () => {
    const keyword = container.querySelector("#input-search").value.toLowerCase();
    if (!keyword) {
      renderRows(calculationResults);
      return;
    }

    const filtered = calculationResults.filter(r => 
      (r.商品名 || "").toLowerCase().includes(keyword) ||
      (r.商品コード || "").toLowerCase().includes(keyword)
    );
    renderRows(filtered);
  });

  // 計算実行ボタン
  container.querySelector("#btn-calculate").addEventListener("click", executeCalculation);

  // 条件クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#store-select").value = "";
    container.querySelector("#category-select").value = "";
    container.querySelector("#period-start").value = "";
    container.querySelector("#period-end").value = "";
    container.querySelector("#safety-stock").value = "";
    container.querySelector("#lead-time").value = "";
    container.querySelector("#order-point").value = "";

    // 表示リセット
    container.querySelector("#forecast-display").innerHTML = 
      '<p class="muted">計算条件を設定して「計算実行」ボタンをクリックしてください。</p>';
    container.querySelector("#current-stock").textContent = "-";
    container.querySelector("#display-safety-stock").textContent = "-";
    container.querySelector("#display-lead-time").textContent = "-";
    container.querySelector("#display-order-point").textContent = "-";

    calculationResults = [];
    renderRows([]);
  });

  // CSVエクスポートボタン
  container.querySelector("#btn-export").addEventListener("click", () => {
    if (calculationResults.length === 0) {
      showError("エクスポートするデータがありません");
      return;
    }

    const headers = ["商品名", "商品コード", "予測需要量", "現在在庫", "安全在庫", "推奨発注量", "発注タイミング"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...calculationResults.map(r => [
        `"${r.商品名 || ""}"`,
        `"${r.商品コード || ""}"`,
        r.予測需要量 || 0,
        r.現在在庫 || 0,
        r.安全在庫 || 0,
        r.推奨発注量 || 0,
        `"${r.発注タイミング || ""}"`
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `発注量計算結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 5. 行レベル操作のイベントデリゲーション
  container.addEventListener("click", async (e) => {
    // 商品詳細リンク
    const productLink = e.target.closest(".product-detail-link");
    if (productLink) {
      e.preventDefault();
      // 商品詳細画面への遷移（実装されている場合）
      // window.showScreen("product-detail-screen");
      return;
    }

    // 詳細ボタン
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      const result = calculationResults.find(r => r.id === id);
      if (result) {
        alert(`商品詳細\n商品名: ${result.商品名}\n予測需要量: ${result.予測需要量}\n推奨発注量: ${result.推奨発注量}`);
      }
      return;
    }

    // 発注ボタン
    const orderBtn = e.target.closest(".order-btn");
    if (orderBtn) {
      const id = orderBtn.dataset.id;
      const result = calculationResults.find(r => r.id === id);
      if (result && confirm(`${result.商品名}を${result.推奨発注量}個発注しますか？`)) {
        // 発注データ作成
        const orderData = {
          店舗ID: container.querySelector("#store-select").value,
          商品ID: result.商品ID,
          発注日: new Date().toISOString(),
          納期予定日: new Date(Date.now() + parseInt(container.querySelector("#lead-time").value || 7) * 24 * 60 * 60 * 1000).toISOString(),
          発注数量: result.推奨発注量,
          予測数量: result.予測需要量,
          発注単価: 100, // 仮の単価
          発注金額: result.推奨発注量 * 100,
          発注方法: "AI推奨採用",
          発注ステータス: "発注済",
          仕入先ID: "default-supplier",
          発注理由: "AI需要予測による自動発注",
          自動発注フラグ: true,
          作成者ID: "current-user",
          更新者ID: "current-user"
        };

        const saved = await window.aivicApi.save(10, orderData); // 発注データ
        if (saved) {
          alert("発注が完了しました");
          // 発注管理画面への遷移
          window.showScreen("scr-1778591852463");
        }
      }
      return;
    }
  });

  // 初期化時に店舗データを読み込み
  loadStores();

  // デフォルト値設定
  const today = new Date();
  const nextWeek = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
  container.querySelector("#period-start").value = today.toISOString().split('T')[0];
  container.querySelector("#period-end").value = nextWeek.toISOString().split('T')[0];
}
